# validation of note strings via simple checks
import re
bad = 0
for l in LESSONS:
    for s in [l["demo"], (l["exercise"] or {}).get("notes", "")]:
        for tok in s.split():
            if tok == "|": continue
            for p in tok.split(":")[0].split("+"):
                if p != "R" and not re.fullmatch(r"[A-G][0-9]", p): print("bad token", l["id"], tok); bad += 1
    assert l["quiz"]["answer"] < len(l["quiz"]["options"])
print(len(LESSONS), "lessons", bad, "bad")
open("/tmp/lessons.txt", "w", encoding="utf-8").write("\n".join(l["id"] + "\t" + l["demo"] + "\t" + (l["exercise"] or {"notes": ""})["notes"] for l in LESSONS))
